import orderItem from '../../order/orderItem.vue';
export default {
	props: {
		// 最高排行数组
		rankingTopOrders: {
			type: Array,
			default() {
				return [];
			}
		},
		// 最低排行数组
		rankingLastOrders: {
			type: Array,
			default() {
				return [];
			}
		},
		// 日期排行榜类型 （年，月） 根据页面上日期筛选类型展示
		rankingDateType: {
			type: Number,
			default() {
				return 0;
			}
		},
	},
	data() {
		return {
			swiperIndex: 0, // 当前swiper所在的current
		};
	},
	created() {},
	methods: {
		changeRanking() {
			switch (this.swiperIndex) {
				case 0:
					this.swiperIndex = 1;
					break;
				case 1:
					this.swiperIndex = 0;
					break;
			}
		}
	},
	components: { orderItem }
};
